<template>
  <FollowupController ref="controllerRef" v-bind="props" v-slot="{controller:r}" @changed="emit('changed')" @source-refreshed="emit('source-refreshed')" @dirty-changed="emit('dirty-changed',$event)" @count-changed="emit('count-changed',$event)" @busy="emit('busy',$event)">
    <section class="followup-panel v2-repair-followups">
      <div class="v2-repair-followup-heading"><div><h3>{{r.editingRecordId?(r.v2EditingHistory?'编辑历史跟进':'历史跟进详情'):'本次跟进'}}</h3><small v-if="r.editingRecordId">{{r.repairDisplayTime(r.selectedRecord?.created_time) || '时间未填写'}}</small></div><div class="v2-repair-inline-actions"><NButton v-if="r.editingRecordId&&!readOnly&&!r.v2EditingHistory" data-v2-navigation size="small" :disabled="r.saving||r.binding" @click="r.v2EditHistory"><Pencil :size="14" />编辑这条</NButton><NButton v-if="!readOnly&&r.editingRecordId" data-v2-navigation size="small" type="primary" secondary :disabled="r.saving||r.binding" @click="r.requestStartCreate"><Plus :size="15" />新增跟进</NButton><NButton v-if="!readOnly" data-v2-navigation size="small" quaternary :disabled="r.saving||r.binding" @click="r.openFollowupBindPicker">关联已有跟进</NButton><NButton data-v2-navigation quaternary circle size="small" aria-label="刷新历史跟进" title="刷新跟进记录" :disabled="r.saving||r.binding" :loading="r.loading||r.sourceRefreshing" @click="r.requestRefresh"><RefreshCw :size="16" /></NButton></div></div>
      <NAlert v-if="r.v2ReadError" type="error" :bordered="false">{{r.v2ReadError}}<NButton text data-v2-navigation :disabled="r.loading" @click="r.requestRefresh">重新读取</NButton></NAlert>
      <NAlert v-if="r.v2Submission.pending.value" :type="r.v2Submission.status.value==='failed'?'error':'warning'" :bordered="false">{{r.v2Submission.message.value}}<NButton text :disabled="r.v2Submission.checking.value" @click="r.v2Submission.check(true,true)">核验原任务</NButton></NAlert>
      <NAlert v-if="r.conflictState" type="warning" :bordered="false">{{r.conflictState.message}}<div class="v2-repair-inline-actions"><NButton data-v2-navigation size="small" @click="r.copyCurrentFollowupDraft">复制当前填写</NButton><NButton size="small" :disabled="r.loading" @click="r.reloadLatestFollowup">读取最新内容</NButton></div></NAlert>
      <NAlert v-else-if="r.message" :type="tone(r.messageTone)" :bordered="false">{{r.message}}</NAlert>

      <div v-if="r.loading&&!r.fields.length" class="v2-repair-skeleton" aria-label="正在读取跟进字段"><NSkeleton text :repeat="7" /></div>
      <NEmpty v-else-if="!r.fields.length" :description="r.v2ReadError?'跟进字段暂不可用':'暂无跟进字段'" />
      <template v-else-if="!readOnly||r.editingRecordId">
        <section class="v2-repair-devices" :class="{'has-error':r.ledgerSelectionError}"><header><strong>关联设备 <small>{{r.ledgerDeviceIds.length?'已选 '+r.ledgerDeviceIds.length+' 台':'必选，可多选'}}</small></strong><NButton v-if="!r.v2Locked" data-v2-navigation size="small" secondary type="primary" :disabled="r.saving" @click="r.ledgerPickerOpen=true"><Server :size="15" />{{r.ledgerDeviceIds.length?'调整设备':'选择台账设备'}}</NButton></header><div v-if="r.ledgerDeviceIds.length" class="v2-repair-device-tags"><NTag v-for="id in r.ledgerDeviceIds" :key="id" :closable="!r.v2Locked&&!r.saving" :bordered="false" @close="r.v2RemoveLedger(id)">{{r.v2LedgerLabel(id)}}</NTag></div><p v-if="r.ledgerSelectionError" class="v2-repair-field-error" role="alert">请选择至少一台台账设备。</p></section>
        <section v-for="group in orderedGroups(r)" :key="group.key" class="v2-repair-followup-section" :class="{'is-progress-section':group.key==='progress','is-execution-section':group.key==='execution'}"><header><h3>{{group.label}}</h3><div v-if="group.key==='equipment'" class="v2-repair-inline-actions"><NButton v-if="!r.v2Locked&&r.v2EquipmentOpen" data-v2-navigation text size="small" :disabled="r.loading||r.saving" :loading="r.equipmentRefreshing" @click="r.refreshEquipmentOptions"><RefreshCw :size="14" />刷新设备选项</NButton><NButton data-v2-navigation text size="small" @click="r.v2EquipmentOpen=!r.v2EquipmentOpen">{{r.v2EquipmentOpen?'收起设备信息':'展开设备信息'}}</NButton></div></header>
          <div v-show="group.key!=='equipment'||r.v2EquipmentOpen" class="v2-repair-field-grid"><div v-if="group.key==='execution'" class="v2-repair-spares v2-repair-field-compact"><NSwitch :value="r.involvesSpareParts" :disabled="r.saving||r.v2Locked" aria-label="是否更换备件" @update:value="r.v2ToggleSpare" /><span>涉及更换备件</span></div><template v-for="field in r.v2SectionFields(group)" :key="field.field_name"><RepairPeoplePicker v-if="r.isWorkerField(field)" :scope="scope" :input-id="r.followupFieldInputId(field)" :model-value="r.workerPeople" :disabled="r.saving||r.v2Locked" @update:model-value="r.updateWorkerPeople" /><RepairField v-else :class="{'v2-repair-field-summary':field.field_name==='维修进展描述','v2-repair-field-progress':r.isProgressField(field),'v2-repair-field-compact':['跟进项（如有）','后续整改措施（如有）'].includes(field.field_name)}" :field="field" :input-id="r.followupFieldInputId(field)" :label="r.fieldLabel(field.field_name)" :model-value="r.draft[field.field_name]" :wide="field.field_name==='维修进展描述'||r.isProgressField(field)" :percentage="r.isProgressField(field)" :select-options="r.selectOptionsForField(field)" :allow-custom-select="r.isModelField(field)" :disabled="r.saving||r.v2Locked||r.isFollowupFieldDisabled(field)" :placeholder="r.fieldPlaceholder(field)" :number-min="r.isProgressField(field)?0:undefined" :number-max="r.isProgressField(field)?1:undefined" :number-step="r.isProgressField(field)?0.01:'any'" @update:model-value="r.updateFollowupField(field,$event)" /></template></div>
        </section>
      <NCollapse :expanded-names="r.v2HistoryOpen?['history']:[]" @update:expanded-names="r.v2HistoryOpen=expanded($event)">
        <NCollapseItem :title="'历史跟进 · '+(r.v2Ready?r.total:'—')+' 条'" name="history">
          <div class="v2-repair-history-search"><NInput :value="r.followupQuery" clearable placeholder="搜索历史跟进" :input-props="{'aria-label':'搜索历史跟进'}" @update:value="r.followupQuery=$event"><template #prefix><Search :size="15" /></template></NInput></div>
          <div v-if="r.loading&&!r.records.length" class="v2-repair-skeleton"><NSkeleton height="48px" :repeat="2" /></div>
          <NEmpty v-else-if="!r.timelineRecords.length" description="暂无匹配的跟进记录" />
          <div v-else class="v2-repair-history" aria-label="历史跟进记录"><button v-for="item in r.timelineRecords" :key="item.record_id" type="button" data-v2-navigation :disabled="r.saving||r.binding" :class="{active:r.editingRecordId===item.record_id}" @click="r.requestSelectRecord(item)"><span><strong>{{item.title || '未命名跟进'}}</strong><small>{{r.repairDisplayTime(item.created_time)||'时间未填写'}}<template v-if="r.isOutsideFilterRecord(item)"> · 当前编辑，筛选外</template></small></span><b>{{r.progressLabel(item.progress)}}</b><ChevronRight :size="16" /></button></div>
          <NPagination v-if="r.pageCount>1" :page="r.page" :page-count="r.pageCount" :disabled="r.loading||r.saving||r.binding" :page-slot="4" @update:page="value=>r.requestChangePage(value-r.page)" />
        </NCollapseItem>
      </NCollapse>
        <NCollapse><NCollapseItem title="智航 CMDB 设备关联（可选）" name="cmdb"><div class="v2-repair-cmdb-line"><span>{{r.selectedCmdbLabel}}</span><NButton v-if="!r.v2Locked" data-v2-navigation size="small" :disabled="r.saving" @click="r.openCmdbPicker">{{r.cmdbRecordIds.length?'重新选择':'选择 CMDB 设备'}}</NButton></div></NCollapseItem></NCollapse>
        <footer v-if="!embedded" class="followup-action-bar v2-repair-followup-footer"><span :class="r.followupSaveStateTone">{{r.editingRecordId&&!r.v2EditingHistory?'查看历史记录':r.followupSaveStateText}}</span><div class="v2-repair-inline-actions"><NButton v-if="r.editingRecordId&&canDelete&&!readOnly&&r.v2EditingHistory" data-v2-navigation quaternary type="error" :disabled="r.saving" @click="r.requestDeleteRecord">删除这条</NButton><NButton v-if="!r.v2Locked" type="primary" :disabled="action.disabled" :loading="r.saving" data-v2-submit @click="r.saveRecord"><Save :size="16" />{{r.editingRecordId?'保存跟进修改':'保存本次跟进'}}</NButton></div></footer>
      </template>
      <ConfirmDialog :open="r.deleteDialogOpen" tone="danger" title="删除当前跟进？" message="删除后无法恢复，只删除当前这一条跟进记录。" confirm-label="确认删除" @resolve="r.resolveDeleteConfirmation" />
      <ConfirmDialog :open="r.discardDialogOpen" tone="warning" title="放弃当前跟进修改？" message="继续后，当前未保存的跟进内容会丢失。" confirm-label="放弃并继续" @resolve="r.resolveDiscardConfirmation" />
      <RepairLedgerPicker compact-mobile :open="r.ledgerPickerOpen" :scope="scope" :selected-ids="r.ledgerDeviceIds" :selected-records="r.ledgerDevices" @close="r.ledgerPickerOpen=false" @confirm="r.confirmLedger" />
      <RecordPickerDialog :open="r.bindPickerOpen" title="绑定已有跟进记录" :records="r.bindCandidates" :columns="r.bindCandidateColumns" :selected-ids="r.bindSelectedIds" multiple :loading="r.bindLoading||r.binding" :has-more="r.bindCandidatesHaveMore" :result-note="r.bindCandidateNote" :query="r.bindQuery" search-placeholder="搜索维修简述、名称或来源" @update:query="r.bindQuery=$event" @search="r.loadBindCandidates(true)" @load-more="r.loadBindCandidates(false)" @close="r.closeFollowupBindPicker" @confirm="r.confirmFollowupBinding" />
      <RecordPickerDialog :open="r.cmdbPickerOpen" title="选择 CMDB 设备" :records="r.cmdbCandidates" :columns="r.cmdbColumns" :selected-ids="r.cmdbRecordIds" multiple allow-empty :loading="r.cmdbLoading" :has-more="r.cmdbCandidatesHaveMore" :result-note="r.cmdbCandidateNote" :status-message="r.cmdbPickerMessage" :status-tone="r.cmdbPickerMessageTone" :query="r.cmdbQuery" @update:query="r.cmdbQuery=$event" @search="r.loadCmdbCandidates(true)" @load-more="r.loadCmdbCandidates(false)" @close="r.closeCmdbPicker" @confirm="r.confirmCmdb"><template #toolbar-actions><NButton v-if="r.cmdbCanForceRefresh" :loading="r.cmdbCacheRefreshing" @click="r.refreshCmdbLocalCache"><CloudDownload :size="15" />同步本地 CMDB</NButton></template></RecordPickerDialog>
    </section>
  </FollowupController>
</template>
<script setup lang="ts">
import {NAlert,NButton,NCollapse,NCollapseItem,NEmpty,NInput,NPagination,NSkeleton,NSwitch,NTag} from 'naive-ui';
import {computed,ref} from 'vue';
import {ChevronRight,CloudDownload,Pencil,Plus,RefreshCw,Save,Search,Server} from 'lucide-vue-next';
import FollowupController from '../components/RepairFollowupPanel.vue';
import RepairPeoplePicker from '../components/RepairPeoplePicker.vue';
import RepairLedgerPicker from '../components/RepairLedgerPicker.vue';
import RecordPickerDialog from '../components/RecordPickerDialog.vue';
import ConfirmDialog from './RepairConfirmation.vue';
import RepairField from './RepairField.vue';
const props=defineProps<{scope:string;summaryRecordId:string;summaryTitle:string;embedded?:boolean;readOnly?:boolean;canDelete?:boolean;refreshVersion?:number;userId?:string}>();
defineOptions({inheritAttrs:false});
const emit=defineEmits<{changed:[];'source-refreshed':[];'dirty-changed':[value:boolean];'count-changed':[value:number];busy:[value:boolean]}>();
const tone=(value:string)=>value==='failed'?'error':value==='warning'?'warning':'success';
function expanded(value:unknown){return Array.isArray(value)&&value.length>0;}
function orderedGroups(r:any){const order=['progress','execution','equipment'];return [...r.groupedFields].sort((a,b)=>order.indexOf(a.key)-order.indexOf(b.key));}
const controllerRef=ref<any>(null);
const action=computed(()=>{const r=controllerRef.value?.v2Controller;const unresolved=r?.v2Submission.pending.value&&r.v2Submission.status.value!=='failed';return {reason:!r||r.loading?'正在读取跟进资料':unresolved?'正在核验原任务':r.conflictState?'请先核对最新记录':r.v2Locked?'查看已保存跟进':r.editingRecordId&&!r.followupDirty?'暂无修改':!r.hasDraftContent?'填写本次处理内容后保存':!r.ledgerDeviceIds.length?'还需选择关联设备':'',editable:Boolean(r&&!r.v2Locked),disabled:!r||r.saving||r.binding||r.loading||r.conflictState||unresolved||(r.editingRecordId?!r.followupDirty:!r.hasDraftContent),busy:Boolean(r?.saving||r?.binding||r?.v2Submission.checking.value),label:r?.editingRecordId?'保存跟进修改':'保存本次跟进',canDelete:Boolean(props.canDelete&&r?.editingRecordId&&r?.v2EditingHistory&&!props.readOnly)};});
defineExpose({action,save:()=>controllerRef.value?.v2Controller.saveRecord(),remove:()=>controllerRef.value?.v2Controller.requestDeleteRecord(),create:()=>controllerRef.value?.v2Controller.requestStartCreate()});
</script>
